#!/usr/bin/env node
// bundle_standalone.js — Option C: self-extracting single-file JS bundle
//
// Produces dist/sclang_standalone.js and dist/scsynth_standalone.js.
// Each output file has all WASM/data assets base64-embedded and requires
// only a standard Node.js installation to run (no adjacent files needed).
//
// Usage:
//   node bundle_standalone.js [--sclang] [--scsynth] [--out-dir <dir>]
//   node bundle_standalone.js             # bundles both by default

'use strict';

const fs   = require('node:fs');
const path = require('node:path');

// ── CLI args ──────────────────────────────────────────────────────────────────

const args = process.argv.slice(2);
const outDir = (() => {
  const i = args.indexOf('--out-dir');
  return i !== -1 ? args[i + 1] : 'dist';
})();

const doSclang  = args.includes('--sclang')  || (!args.includes('--scsynth'));
const doScsynth = args.includes('--scsynth') || (!args.includes('--sclang'));

// ── Helpers ───────────────────────────────────────────────────────────────────

function b64(filePath) {
  if (!fs.existsSync(filePath)) return null;
  return fs.readFileSync(filePath).toString('base64');
}

function fileSize(filePath) {
  if (!fs.existsSync(filePath)) return '(not found)';
  const bytes = fs.statSync(filePath).size;
  return bytes >= 1024 * 1024
    ? `${(bytes / (1024 * 1024)).toFixed(1)} MB`
    : `${(bytes / 1024).toFixed(0)} KB`;
}

// ── Bundle template ───────────────────────────────────────────────────────────
// The generated file:
//   1. Decodes base64 blobs into Buffers at startup
//   2. Writes the .data preload package to a temp file (Emscripten reads it
//      via locateFile; writing to a temp dir avoids any cwd dependency)
//   3. Passes wasmBinary directly so the .wasm is never read from disk
//   4. Delegates all remaining argv handling to the original CLI module

function makeBundle({ entryFile, moduleJsFile, wasmFile, dataFile, moduleName }) {
  const wasmB64 = b64(wasmFile);
  if (!wasmB64) {
    console.error(`✗ Missing: ${wasmFile}`);
    process.exit(1);
  }
  const dataB64 = dataFile ? b64(dataFile) : null;

  const wasmSize = fileSize(wasmFile);
  const dataSize = dataFile ? fileSize(dataFile) : null;

  // Read the original CLI entry and module JS, embed them inline as strings
  // so the bundle truly has zero external file dependencies at runtime.
  const entrySource   = fs.readFileSync(entryFile,   'utf8');
  const moduleJsSource = fs.readFileSync(moduleJsFile, 'utf8');

  // We need to patch the Emscripten factory so it never touches the filesystem
  // for the .wasm or .data files.  We do this by wrapping the factory export
  // and intercepting the module options before the factory runs.
  return `\
#!/usr/bin/env node
// AUTO-GENERATED by bundle_standalone.js — do not edit by hand.
// ${moduleName} standalone bundle (Option C – base64 embedded assets)
//
// Embedded assets:
//   ${path.basename(wasmFile)}: ${wasmSize}${dataSize ? `\n//   ${path.basename(dataFile)}: ${dataSize}` : ''}
//
// Run: node ${path.basename(entryFile.replace(/\.js$/, '_standalone.js'))} [args...]
'use strict';

const os   = require('node:os');
const fs   = require('node:fs');
const path = require('node:path');

// ── Decode embedded assets ────────────────────────────────────────────────────

const WASM_B64 = ${JSON.stringify(wasmB64)};
${dataB64 ? `const DATA_B64 = ${JSON.stringify(dataB64)};` : 'const DATA_B64 = null;'}

const wasmBuf = Buffer.from(WASM_B64, 'base64');
const dataBuf = DATA_B64 ? Buffer.from(DATA_B64, 'base64') : null;

// ── Write .data preload to a temp file ────────────────────────────────────────
// Emscripten's preload package loader reads this file synchronously at startup.
// We write it to a temp dir so there are no cwd or install-location assumptions.

let dataTmpPath = null;
if (dataBuf) {
  dataTmpPath = path.join(os.tmpdir(), '${moduleName.toLowerCase()}_${path.basename(dataFile || '')}');
  fs.writeFileSync(dataTmpPath, dataBuf);
}

// ── Patch instantiateEmscriptenModule ─────────────────────────────────────────
// Override require() for hc_runtime so we can inject wasmBinary + locateFile
// before the Emscripten factory runs, bypassing all file-system lookups.

const Module = require('node:module');
const _originalLoad = Module._load.bind(Module);
Module._load = function(request, parent, isMain) {
  // Intercept the Emscripten factory module (loaded by runtime_utils)
  if (request && (
    request.endsWith('${path.basename(moduleJsFile)}') ||
    request.includes('${path.basename(moduleJsFile)}')
  )) {
    const OrigFactory = _originalLoad(request, parent, isMain);
    return async function PatchedFactory(opts = {}) {
      const patched = {
        ...opts,
        wasmBinary: wasmBuf,
      };
      if (dataTmpPath) {
        const origLocate = opts.locateFile;
        patched.locateFile = (f, scriptDir) => {
          if (f.endsWith('.data')) return dataTmpPath;
          return origLocate ? origLocate(f, scriptDir) : (scriptDir || '') + f;
        };
      }
      return OrigFactory(patched);
    };
  }
  return _originalLoad(request, parent, isMain);
};

// ── Launch the CLI ────────────────────────────────────────────────────────────
// Resolve paths relative to the original source tree so require() chains work.
// __dirname here is meaningless (we are a bundle), so we resolve against the
// directory of the original entry file baked in below.

const ENTRY_DIR = ${JSON.stringify(path.dirname(path.resolve(entryFile)))};
const mod = require('node:module').createRequire(ENTRY_DIR + '/');

// Re-run the CLI entry in the context of its original directory.
process.chdir(ENTRY_DIR);
require(${JSON.stringify(path.resolve(entryFile))});
`;
}

// ── Bundle definitions ────────────────────────────────────────────────────────

const CLI_DIR    = path.resolve(__dirname);
const BUILD_DIR  = path.resolve(__dirname, '..', 'build/wasm');

const targets = [];

if (doSclang) {
  targets.push({
    name:       'hclang_standalone',
    moduleName: 'HClang',
    entryFile:  path.join(CLI_DIR, 'hclang.js'),
    moduleJsFile: path.join(BUILD_DIR, 'lang/hclang/hclang.js'),
    wasmFile:   path.join(BUILD_DIR, 'lang/hclang/hclang.wasm'),
    dataFile:   path.join(BUILD_DIR, 'lang/hclang/hclang.data'),
  });
}

if (doScsynth) {
  targets.push({
    name:       'hcsynth_standalone',
    moduleName: 'HCSynth',
    entryFile:  path.join(CLI_DIR, 'hcsynth.js'),
    moduleJsFile: path.join(BUILD_DIR, 'server/hcsynth/hcsynth.js'),
    wasmFile:   path.join(BUILD_DIR, 'server/hcsynth/hcsynth.wasm'),
    dataFile:   path.join(BUILD_DIR, 'server/hcsynth/hcsynth.data'),
  });
}

// ── Write output files ────────────────────────────────────────────────────────

const absOutDir = path.resolve(outDir);
fs.mkdirSync(absOutDir, { recursive: true });

for (const t of targets) {
  process.stdout.write(`Bundling ${t.name}... (this may take a moment)\n`);

  const source = makeBundle(t);
  const outPath = path.join(absOutDir, `${t.name}.js`);
  fs.writeFileSync(outPath, source, 'utf8');
  fs.chmodSync(outPath, 0o755);

  const outSize = fileSize(outPath);
  console.log(`✓ ${outPath} (${outSize})`);
}

console.log(`\nDone. Run with: node ${absOutDir}/<name>.js [args...]`);
